#include <stdlib.h>
#include <string.h>

#if defined(__AVX512F__)
#define VL 16
#define MR 8
#else
#define VL 8
#define MR 6
#endif
#define NR (2 * VL)
#define KC 256
#define MC (MR * 16)
#define NCMAX 4096
#define JCHUNK (NR * 4)

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
    }
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
    if (first) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = acc[i][0];
            *(vfu *)(c + i * ldc + VL) = acc[i][1];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += acc[i][0];
            *(vfu *)(c + i * ldc + VL) += acc[i][1];
        }
    }
}

static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *ap)
{
    for (int p = 0; p < mc; p += MR) {
        int mr = mc - p < MR ? mc - p : MR;
        for (int k = 0; k < kc; k++) {
            int i;
            for (i = 0; i < mr; i++)
                ap[k * MR + i] = A[(size_t)(i0 + p + i) * n + p0 + k];
            for (; i < MR; i++)
                ap[k * MR + i] = 0.0f;
        }
        ap += (size_t)kc * MR;
    }
}

static void pack_b_panel(const float *B, int n, int p0, int kc, int j0, int nr, float *bp)
{
    for (int k = 0; k < kc; k++) {
        const float *src = B + (size_t)(p0 + k) * n + j0;
        float *dst = bp + (size_t)k * NR;
        int j;
        for (j = 0; j < nr; j++) dst[j] = src[j];
        for (; j < NR; j++) dst[j] = 0.0f;
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    int ncmax = n < NCMAX ? n : NCMAX;
    int ncpmax = (ncmax + NR - 1) / NR * NR;
    size_t bsz = (size_t)KC * ncpmax * sizeof(float);
    bsz = (bsz + 63) / 64 * 64;
    float *bp = (float *)aligned_alloc(64, bsz);

    for (int jc = 0; jc < n; jc += ncmax) {
        int nc = n - jc < ncmax ? n - jc : ncmax;
        int npan = (nc + NR - 1) / NR;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);
            int nib = (n + MC - 1) / MC;
            int njb = (nc + JCHUNK - 1) / JCHUNK;
#pragma omp parallel
            {
                float ap[MC * KC] __attribute__((aligned(64)));
                float tile[MR * NR] __attribute__((aligned(64)));
#pragma omp for schedule(static)
                for (int q = 0; q < npan; q++) {
                    int j0 = q * NR;
                    int nr = nc - j0 < NR ? nc - j0 : NR;
                    pack_b_panel(B, n, pc, kc, jc + j0, nr, bp + (size_t)q * kc * NR);
                }
#pragma omp for collapse(2) schedule(dynamic, 1)
                for (int ib = 0; ib < nib; ib++) {
                    for (int jb = 0; jb < njb; jb++) {
                        int i0 = ib * MC;
                        int mc = n - i0 < MC ? n - i0 : MC;
                        pack_a(A, n, i0, mc, pc, kc, ap);
                        int jstart = jb * JCHUNK;
                        int jend = jstart + JCHUNK < nc ? jstart + JCHUNK : nc;
                        for (int j = jstart; j < jend; j += NR) {
                            int nr = nc - j < NR ? nc - j : NR;
                            const float *bpan = bp + (size_t)(j / NR) * kc * NR;
                            for (int i = 0; i < mc; i += MR) {
                                int mr = mc - i < MR ? mc - i : MR;
                                const float *apan = ap + (size_t)(i / MR) * kc * MR;
                                float *cp = C + (size_t)(i0 + i) * n + jc + j;
                                if (mr == MR && nr == NR) {
                                    kernel(kc, apan, bpan, cp, n, first);
                                } else {
                                    kernel(kc, apan, bpan, tile, NR, 1);
                                    for (int ii = 0; ii < mr; ii++) {
                                        float *crow = cp + (size_t)ii * n;
                                        const float *trow = tile + ii * NR;
                                        if (first)
                                            for (int jj = 0; jj < nr; jj++) crow[jj] = trow[jj];
                                        else
                                            for (int jj = 0; jj < nr; jj++) crow[jj] += trow[jj];
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    free(bp);
}
